def make(i,kind,answers,marks,gradeNotes,essential,triggered=False):
 a=[x.strip() for x in answers.split('||')] if isinstance(answers,str) else answers
 assert len(a)==len(marks)==len(gradeNotes)==6
 raw=sum(map(sum,marks));final=min(raw,14) if triggered else raw
 return {'materialId':b[i]['id'],'goalId':b[i]['requires'][0],'kind':kind,'completeCaseAAndCaseBSubmission':True,'ownAnswers':[{'taskId':('A' if n<3 else 'B')+str(n%3+1),'answerDe':a[n],'individualOwnCriterionPoints':marks[n],'stepPoints':sum(marks[n]),'manualDecisionDe':gradeNotes[n],'wholeActualRubric':b[i]['examData']['scoring']['steps'][n]} for n in range(6)],'wholeEssentialPerformanceDecisionDe':essential,'actualWholeBoundaryTriggered':triggered,'rawPoints':raw,'finalPoints':final,'maxPoints':24,'passingPoints':15,'actualResult':'PASS' if final>=15 else 'FAIL','sourceOfAnswersAndGrades':'independent_reviewer_actual_own_written_work_not_author_replay'}
for i in range(12):
 a=[x.strip() for x in fair[i].split('||')];assert len(a)==6
 rows.append(make(i,'FAIR_IMPERFECT_COMPLETE_TWO_CASE_WORK',a,fairmarks[i],notes[i],'Alle erforderlichen ganzen Kernleistungen sinnvoll vorhanden. Einzelne fehlende Details begrenzen Teilpunkte, kein Entireabsence-cap und keine ideale Musterformulierung nötig.'))
 rows.append(make(i,'ENTIRE_SECOND_APPLICATION_OMITTED_REAL_COMPLETE_SUBMISSION',a[:3]+['Kein Beitrag zu dieser zweiten Anwendung eingereicht.']*3,fairmarks[i][:3]+[[0]*len(x) for x in fairmarks[i][3:]],notes[i][:3]+['B tatsächlich ganz ausgelassen; kein belegter Teil dieser Variante.']*3,'Die zweite unabhängige Anwendung fehlt tatsächlich ganz. Raw bleibt wegen der tatsächlichen dreiA-Aufträge ohnehin unter15; die Grenze erhöht Punkte nie.',True))
# Eight further actual independent whole essential-absence works. Four demonstrated PASS-bypasses live in the separate finding file.
cores={
0:('Keine begründete konkrete Schutzstrategie gewählt; Engpassrechnung ohne erforderliche strategische Bewertung.', '''Der Chip ist aus dem einzigen Spezialwerk nötig.400/100=4 Wochen;200 deckt den zweiwöchigen,1000 nicht den zehnwöchigen Bedarf, dort fehlen600. Für die sofortige Produktion ist das ein Engpass.
||Zu Schutzmöglichkeiten liefere ich keine Antwort.
||Wahrscheinlichkeit des Schocks, Stillstandskosten und Qualifikation müssten erhoben werden. Ich wähle und begründe keine Maßnahme; diese Angaben allein bilden noch keine Resilienzstrategie.
||Die zwei Firmen teilen Becken und Hafen, also einen Störungspfad.160 deckt zwei Wochen; verschiedene Namen machen die Wege nicht unabhängig.
||Zu alternativen Schutzmöglichkeiten liefere ich keine Antwort.
||Die sechs Wochen erfordern480 Chips. Exakte Ausfallwahrscheinlichkeit und sichere Lieferfähigkeit des unabhängigen Weges bleiben offen. Ich entscheide nicht zwischen Schutzoptionen und wäge weder ihre Kosten noch eine Umsetzung ab.''',[[2,2],[0,0],[0,2],[2,2],[0,0],[0,2]],True),
1:('UN-Rolle und UN-Grenzen vollständig fehlen in beiden neuen Fällen.', '''WTO-Verfahren können die technischen Handelsanforderungen betreffen, IWF die Zahlungsbilanzfinanzierung, Weltbank das Wasserprojekt. Für die UN wird keine Rolle erläutert.
||WTO-Mitgliederregeln und Verfahren, bedingtes IWF-Programm sowie geprüfte Weltbankprojekte begrenzen die drei genannten Wege. Eine UN-Grenze untersuche ich nicht.
||Makrofinanzierung kann langfristige Projektarbeit ermöglichen, ersetzt sie aber nicht. Zusage und tatsächliche Wasserlieferung sind verschieden; die Einheitsbehörde ist wegen dieser drei Mandate unrealistisch. Ich lasse die UN vollständig unberücksichtigt.
||WTO betrifft Reparaturgüterhindernisse, IWF Devisenabfluss, Weltbank den Brückenaufbau. Über die UN gibt es in meiner Antwort keinen Beitrag.
||Ein IWF-Kredit bedeutet keine fertige Brücke; WTO-Regeln sind keine Projektfinanzierung. Das sind zwei verschiedene Schnittstellen mit Verfahren und Umsetzung. UN-Empfehlung und Koordination behandle ich nicht.
||Ich priorisiere Devisen- und Projektfinanzierung nach tatsächlicher Lieferfähigkeit; Gegenposition richtet zuerst Brücken wieder her. Kosten, Geldverfügbarkeit und reale Fertigstellung müssten untersucht werden. Die UN bleibt auch hier ohne Rolle oder Grenze.''',[[1,1,1,0],[1,1,1,0],[2,2],[1,1,1,0],[2,1],[2,2]],True),
2:('Zeit- und Rechts-/Ankündigungsstatus in beiden tatsächlichen Dossiers durchgehend falsch.', '''Die2024erAnkündigung sei bereits der am selben Tag wirksame Rechtsakt. Alle100-Prozent-EV-Zölle und sämtliche Agrarmaßnahmen gelten bis heute ohne jede Aufhebung oder Ausnahme; die März2026-Angaben ignoriere ich als folgenlose Vermutung.
||Ein höherer EV-Importpreis könnte heimische Anbieter stützen und Käufer belasten. Agrarreaktionen können Exporteure und Beschäftigte belasten; Komponenten brauchen ihren eigenen Produktscope und dürfen nicht identisch behandelt werden.
||Neben politischen Maßnahmen könnte weniger chinesische Gesamtnachfrage Exporte senken. Mengen, Nachfrage und Produktdaten sind nötig, und das Parteiwort ungerechtfertigt ist kein Gerichtsurteil. Für einzelne Unternehmen gibt es kein gleiches Resultat.
||Alle Exportkontrollen seien vollständig aufgehoben und jedes Unternehmen habe eine sichere Lizenz erhalten. Die Gespräche8./9. Oktober bedeuteten bereits einen belegten konkreten Lizenzdeal für die Motorfirma und keine offene Umsetzung.
||Der fiktive Input steigt15 und Transport3;85→103 ergibt18/85≈21,18 Prozent. Diese getrennten Veränderungen rechtfertigen keine einzige automatisch politische Ursache, keine echte heute beobachtete Kostenwirkung.
||Inputanwender wollen Versorgung und stabile Preise, Staaten Sicherheitskontrolle, Produzenten verschiedene Absatzchancen. Eine Alternative braucht wirklich erlaubte Lieferfähigkeit und Qualifikation. Preise, reale Mengen und Abwicklung müssten beobachtet werden; rechtswidrige Umgehung ist keine Lösung.''',[[0,0],[2,2],[2,2],[0,0],[2,2],[2,2]],True),
3:('SDG-Einordnung vollständig fehlt trotz richtiger Paris-, Kosten- und Zugangsprüfung.', '''Dieselsubstitution kann Paris-Minderung und den nationalen Klimabeitrag betreffen, Zuschüsse seine Unterstützung. Bauoutput ist keine reale Emissionsverringerung. SDGs nenne oder klassifiziere ich nicht.
||4+8=12 Mio deckt Investition, nicht Betrieb. Vermiedene Dieselbelastung kann externe Schäden verringern,200 einmalige Zahlung Arme ausschließen. Wartung und tatsächliche Nutzung fehlen.
||Ich würde finanzierte Entlastung und Wartung verlangen; Gegenposition fordert einen Pilot. Tatsächliche Dieselsubstitution und Nutzung nach Einkommen sind Daten. Das Paris-Verfahren ist keine automatische Weltsteuer oder Erfolgsgarantie; einen SDG-Bezug prüfe ich nicht.
||Paris-Anpassung verringert Schadensanfälligkeit, Minderung begrenzt Emissionen; Anpassung beendet Erwärmung nicht.13 gegen10 lässt3 fehlen und eine Zusage ist nicht bewilligt. Wasser/Nahrung ordne ich keinem SDG zu.
||Knappheit verursacht Verdrängung, ärmere gefährdete Gruppen können besonders profitieren; Minderung wirkt grenzüberschreitend. Bewilligte3 garantieren keine tragfähige Wartung oder Verteilung.
||Ich priorisiere akute gefährdete Versorgung mit erhaltenem Minderungsplan. Gegenposition gewichtet dauerhafte Emissionsminderung stärker. Paris-Transparenz verlangt passende Ergebnisse und Finanzdaten, beweist aber keinen Erfolg. Eine konkrete SDG-Leistung fehlt in meiner gesamten Arbeit.''',[[0,1,2],[2,2],[2,2],[1,2],[2,2],[2,2]],True),
6:('Das gelenkte Regime wird in beiden Fällen vollständig ausgelassen, die beiden anderen richtig verglichen.', '''Fest erleichtert Wechselkursplanung und braucht bei offenen Kapitalflüssen passende Politik, Flex lässt Schwankungen bei größerer Zinsautonomie zu. Ich beurteile ausschließlich diese beiden Regime, nicht Gelenkt.
||Für feste Verteidigung reichen60/15 vier Wochen unter dem Modellabfluss; Erwartungen und Mindestreserven können das ändern. Flex bleibt nominal riskant. Eine Interventionspraxis des gelenkten Regimes wird nicht geprüft.
||Ich wähle Flex bei knappen Reserven, Gegenposition einen glaubwürdigen Festanker. Exposure, Inflation und tatsächliche Devisen fehlen. Mein Urteil vergleicht nur Fest und Flex.
||100 Fremdwährung entsprechen zunächst200 und danach300 heimisch, eine50-Prozent-Mehrlast nach Kurs2→3. Fest kann den Sprung nur bei verteidigbarer Parität verhindern, Flex passt an. Gelenkt bleibt unbeschrieben.
||20/10 ergibt zwei Monate fester Modellverteidigung; Flex belastet Fremdwährungsschuldner trotz möglicher Anpassung. Zur konkreten gelenkten Praxis oder deren Grenzen liefere ich nichts.
||Ich wähle geordnete flexible Anpassung und Expositionsprüfung; Gegenposition finanziert einen glaubwürdigen Festanker. Nachfrage, Kosten und Schulden verhindern automatische Zahlungsfähigkeit durch Abwertung. Gelenkt kommt im ganzen Vergleich nicht vor.''',[[1,1,0,1],[2,2],[2,2],[2,1],[2,1],[2,2]],True),
7:('Chancen-/Lastenverteilung zwischen konkreten Gruppen wird in beiden Fällen vollständig ausgelassen.', '''Der enge Erlös-minus-Importinputs-Saldo ist7 vor und9 nach dem Impuls, also+2 und nicht+4 Mio. Der Handel eröffnet zusätzliche Absatzmenge und kann Maschinenzugang erleichtern, ist aber kein kompletter BIP- oder Gewinnwert.
||Bruttoerlös enthält importierte Inputs, Preisvolatilität und fehlende weitere Daten verhindern ein vollständiges Wertschöpfungsurteil. Über konkrete Folgen für Produzenten, Beschäftigte oder Verbraucher treffe ich keine Aussage.
||Maschinen benötigen Finanzierung, geeignete Auswahl und Wartung. Diversifizierung braucht ebenfalls Absatz. Diese Bedingungen stützen ein vorsichtiges Entwicklungsurteil; unterschiedliche Gruppenwirkungen bleiben vollständig ausgeklammert.
||Die beiden gesetzten Preise fallen120 auf100 und60 auf50; aus der Veränderung folgt ohne Mengen und Nutzung kein genauer produktiver Gesamtgewinn. Welche Gruppen profitieren oder verlieren, prüfe ich nicht.
||40 und30 stammen aus verschiedenen Zeitpunkten und30 hängen von tatsächlichem Absatz ab. Ob bestimmte Betroffene Zugang oder Ersatzchancen haben, behandle ich nicht.
||Ein hypothetischer40−30-Wert10 ist keine beobachtete Nettobilanz. Ein finanzierbares Begleitbudget braucht reale Kosten und Nachfrage. Ich empfehle keinen gruppenspezifischen Ausgleich und analysiere keine ungleichen Verluste oder Chancen.''',[[2,2],[0,2],[2,2],[1,2],[2,0],[1,2]],True),
8:('Gesamtvorteil und tatsächlich finanzierte individuelle Kompensation werden in beiden Fällen durchgehend gleichgesetzt.', '''Unter den gesetzten Mengen erhöht sich der Metallpreis100 auf120, die100 Tonnen kosten12000 statt10000 und damit2000 mehr. Die1000 Importtonnen erzeugen20000 Staatseinnahmen. Metallanbieter können gewinnen, Bauunternehmen und Käufer verlieren; Beschäftigung hängt von Kapazität ab.
||Vorproduktnutzer können trotz geschützter heimischer Anbieter verlieren. Der Gegenzoll ist erst erwogen und könnte Maschinenexporte später treffen. Preisweitergabe und Mengen sind gesetzte Annahmen, keine beobachteten Arbeitsplatzwirkungen.
||Ich gewichte Versorgung und Beschäftigung gegeneinander und würde den Schutz befristen. Alle Belasteten seien aber durch die20000 Einnahmen bereits tatsächlich voll kompensiert, allein weil der Staat diese Summe erhält; individuelle Zahlungen und Zugangsregeln seien unnötig.
||1000×100=100000 private Ersparnis jährlich,30×2000=60000 Kosten für alle Ausbildungsplätze;10 finanzierte Plätze kosten20000. Die30 verlieren sofort,20 mögliche Exportstellen entstehen erst später und bei Absatz/Qualifikation. Aggregate Gewinne seien trotzdem bereits Zahlungen an alle Arbeitslosen.
||Es gebe keine individuelle Kompensationslücke und kein Finanzierungsproblem: die100000 private Gesamtersparnis seien ohne Verwendung oder Transfer bereits allen30 ausgezahlt. Dass nur10 Ausbildungsplätze vorhanden sind, ändere daran nichts.
||Ich würde die Exportnachfrage und Ausbildungsqualität überprüfen, weil sie den späteren Produktionserfolg bestimmen. Aber ein positiver Gesamtnutzen garantiere bereits heute die vollständige individuelle Entschädigung; verschiedene Gruppen und Zeitpunkte benötigten keinen tatsächlichen Transferpfad.''',[[2,2],[2,2],[2,0],[2,2],[0,1],[1,1]],True),
9:('Gini-Messgegenstand in beiden Fällen vollständig falsch als Durchschnittseinkommen ausgelegt.', '''HDI fasst durchschnittliche Gesundheit, Bildung und Lebensstandard zusammen. A hat0,80 statt0,70. Gini0,45 gegen0,25 bedeutet dagegen, dass das Durchschnittseinkommen entsprechend höher ist; relative Ungleichheit messe er nicht.
||Ein geometrisches Mittel erzwingt keinen besseren Teilwert und keinen Vorteil für jeden Menschen. Gerechtigkeit ist ein normatives Kriterium. Der Gini sei jedoch ein Durchschnittseinkommensmaß, kein Verteilungsmaß.
||Teilindizes, Armutsgrenze, Gesundheit und Bildung sollten ergänzt werden. Ich will mein Normkriterium offenlegen und keinen universellen Vorteil folgern. Die Giniwerte interpretiere ich weiter allein als Mittelwerte des Einkommens.
||30/100=0,30 ist numerisch unter0,35, aber Jahre und Einkommen/Konsum unterscheiden sich, daher ist ein aktueller Rangvergleich nicht gesichert. Nach meiner Deutung vergleichen diese Ginis dennoch Durchschnittseinkommen.
||Alle fünf Haushalte verdienen40 und liegen unter50. Ihr Gini entspreche dem Durchschnitt40 und zeige nicht ihre Gleichverteilung. HDI ergänzt durchschnittliche Gesundheit, Bildung und materiellen Standard, nicht jede Person.
||Gleiche Jahre, Konzepte, Population und Erhebungsqualität sowie zusätzliche Armutslage wären nötig. Die Zahlen alleine liefern kein umfassendes Gerechtigkeitsurteil. Meine Gini-Messdeutung wird im ganzen Werk nicht korrigiert.''',[[1,1],[2,1],[2,2],[2,2],[0,2],[2,2]],True)
}
